@overload
def block_card(
    func: Callable[..., Any],
    *,
    label: str = ...,
) -> Callable[..., rx.Component]: ...


def block_card(
    func: Callable[..., Any] | None = None,
    *,
    label: str = "",
) -> Callable[..., rx.Component] | CardDecorator:
    """Decorator wrapper to wrap blocks."""
    if func is None:

        def decorator(f: Callable[..., Any]) -> Callable[..., rx.Component]:
            return block_card(f, label=label)

        return decorator

    @functools.wraps(func)
    def wrapper(*args: object, **kwargs: object) -> rx.Component:
        inner_component = func(*args, **kwargs)  # type: ignore[misc]
        cmd = f"uv run buridan add {func.__qualname__}"
        btn_id = generate_component_id()
        text_id = f"text-{btn_id}"
        return rx.el.div(
            rx.el.div(
                button(
                    hi("TerminalIcon", class_name="size-4 shrink-0"),
                    rx.el.span(cmd, id=text_id),
                    variant="outline",
                    size="sm",
                    id=btn_id,
                    on_click=rx.call_script(f"""
                        const text = document.getElementById({text_id!r});
                        navigator.clipboard.writeText({cmd!r});

                        const original = text.innerText;
                        text.innerText = "Copied!";

                        setTimeout(() => {{
                            text.innerText = original;
                        }}, 1000);
                    """),
                    class_name="min-w-3xs",
                ),
                rx.el.p("︲", class_name="text-muted-foreground/50 font-thin h-6"),
                open_in_reflex_build(
                    icon_light="/svg/reflex/reflex_light.svg",
                    icon_dark="/svg/reflex/reflex_dark.svg",
                    tooltip_content="Open in Reflex Build",
                    href=f"https://build.reflex.dev/?prompt=Install and run pip install buridan-create and buridan init. Then run the following command: buridan add {func.__qualname__}",
                ),
                class_name="flex flex-row gap-x-2 items-center justify-end px-6 sm:px-2",
            ),
            rx.el.div(
                inner_component,
                class_name="break-inside-avoid w-full h-full p-7 flex flex-col",
            ),
            class_name="w-full flex flex-col gap-y-2"
            + rx.cond(
                (selected_blocks_category.value == "all")
                | (selected_blocks_category.value == label),
                " flex",
                " hidden",
            ).to(str),
        )

    return wrapper


